const input = $input.first().json || {};
const prev = $('Preparar Contexto').first().json || {};

let rawOutput = '';
if (typeof input.output === 'string') {
  rawOutput = input.output;
} else if (input.output && typeof input.output.text === 'string') {
  rawOutput = input.output.text;
} else if (typeof input.text === 'string') {
  rawOutput = input.text;
} else if (typeof input.response === 'string') {
  rawOutput = input.response;
} else if (typeof input === 'string') {
  rawOutput = input;
} else {
  rawOutput = String(input.output || 'Hola, soy el asistente de ArtLink.');
}

let suggestions = [];
let quickReplies = [];
let actions = [];
let intent = 'art_explanation';
let knowledgeDomain = 'art';
let requiresConfirmation = false;

// Extraer posible bloque JSON estructurado con intenciones y acciones
const jsonMatch = rawOutput.match(/```(?:json)?([\s\S]*?)```/);
let cleanMessage = rawOutput;

if (jsonMatch) {
  try {
    const parsed = JSON.parse(jsonMatch[1].trim());
    if (parsed.intent && typeof parsed.intent === 'string') {
      intent = parsed.intent;
    }
    if (parsed.knowledgeDomain && typeof parsed.knowledgeDomain === 'string') {
      knowledgeDomain = parsed.knowledgeDomain;
    }
    if (Array.isArray(parsed.suggestions)) {
      suggestions = parsed.suggestions;
    }
    if (Array.isArray(parsed.quickReplies)) {
      quickReplies = parsed.quickReplies;
    }
    if (Array.isArray(parsed.actions)) {
      actions = parsed.actions;
    }
    if (typeof parsed.requiresConfirmation === 'boolean') {
      requiresConfirmation = parsed.requiresConfirmation;
    }
    cleanMessage = rawOutput.replace(/```(?:json)?[\s\S]*?```/, '').trim();
  } catch (e) {
    // Conservar texto original si el JSON interno presenta algún error sintáctico
  }
}

// Si no se detectaron acciones pero se menciona explorar o comisiones, ofrecer acciones predeterminadas útiles
if (actions.length === 0 && /explorar|buscar artistas|artistas/i.test(cleanMessage)) {
  actions.push({
    type: 'open_explore',
    label: 'Explorar artistas',
    filters: {}
  });
}

return [
  {
    json: {
      success: true,
      message: cleanMessage,
      sessionId: prev.sessionId || 'session-default',
      conversationId: prev.conversationId || 'convo-default',
      intent,
      knowledgeDomain,
      suggestions,
      quickReplies,
      actions,
      requiresConfirmation,
      timestamp: new Date().toISOString(),
      model: 'gemini-1.5-flash'
    }
  }
];
